    /** Resolves a port food item; a null here is recorded, never silently dropped. */
    private static void gt(List<GTFoodStats.Row> rows, String id, int alcohol, int caffeine,
                           int dehydration, int sugar, int fat, int radiation) {
        Item item = GTFoodItems.item(id);
        if (item == null) {
            MISSING_IDS.add(id);
            return;
        }
        rows.add(new GTFoodStats.Row(item, alcohol, caffeine, dehydration, sugar, fat, radiation));
    }
